// NB-07 · spec: .qa/e2e/specs/nearby.md 1.7 · две роли · меняет данные (лайк reg1→reg2; мэтч 83f63177 уже есть) → в finally оба false.
import { test, expect } from '../../fixtures';
import { openRole, turnOff, meetPair, tapWhenTop, expandSheet, isRpc, card, NAME } from './nearby-helpers';

test.use({ browserName: 'webkit' });

test.describe('היו כאן — משתמשים שהיו בקרבת מקום', () => {
  test.describe.configure({ timeout: 180_000 });
  test('«אהבתי» на карточке → rpc/swipe like, кнопка становится недоступной @iphone @data (#67c751)', async ({ browser }) => {
    const reg1 = await openRole(browser, 'reg1');
    const reg2 = await openRole(browser, 'reg2');
    try {
      await meetPair(reg1, reg2);
      const p = reg1.page;
      await expandSheet(p); // 375×629: без раскрытия сердце под нижней навигацией
      const heart = card(p, NAME.reg2).getByRole('button', { name: 'אהבתי' });
      const [res] = await Promise.all([p.waitForResponse(isRpc('swipe'), { timeout: 40_000 }), tapWhenTop(p, heart)]);
      expect(res.ok(), 'rpc/swipe').toBeTruthy();
      expect(res.request().postDataJSON()).toMatchObject({ p_target: reg2.id, p_kind: 'like' });
      await expect(heart).toBeDisabled();
      // Мэтч уже был — может всплыть «יש התאמה»; закрыть.
      const goOn = p.getByText('להמשיך לגלות');
      if (await goOn.isVisible()) await goOn.click();
    } finally {
      await turnOff(reg1);
      await turnOff(reg2);
      await reg1.ctx.close();
      await reg2.ctx.close();
    }
  });
});
